<?php if (!defined('BASEPATH')) exit('No direct script access allowed');class Mauth extends CI_Controller {    public function __construct() {        parent::__construct();        $this->load->helper('xssclean');        fnIfCheckUserLoggedIn();        $this->load->model(CNFCOMPANY . "mauthmodel");        $ArrUserLoggedInfo = fnGetUserLoggedInfo('1');        $this->companyid = $ArrUserLoggedInfo['companyid'];        $this->userid = $ArrUserLoggedInfo['id'];        $this->limit = LIMITPERPAGE;    }    public function addedittestingauth() {        $ArrData = array('ArrBasicInfo' => array(), 'VarId' => '');        $VarId = base64_decode(urldecode($this->uri->segment(4)));        $ArrData['Edit'] = $this->uri->segment(5);        if (is_numeric($VarId)) {            $ArrResults = $this->mauthmodel->fnGetInfo('', '', $VarId);            $ArrData['ArrBasicInfo'] = $ArrResults[0];            $ArrData['VarId'] = $ArrResults[0]['id'];        } else {        }        $this->load->view(CNFCOMPANY . 'addedittestingauth', $ArrData);    }    public function updatetestingauthInfo() {        $ArrResult = [];        $VarTestingAuth = xssclean($this->input->post('ta'));        $VarAddress = xssclean($this->input->post('a'));        $VarGst = xssclean($this->input->post('g'));        $VarContactName = xssclean($this->input->post('n'));        $VarEmail = xssclean($this->input->post('e'));        $VarPhone = xssclean($this->input->post('p'));        $VarMobile = xssclean($this->input->post('m'));        $VarStatus = xssclean($this->input->post('s'));        $VarId = xssclean($this->input->post('id'));        if ($VarTestingAuth <> '') {            $ArrUpdateData['id'] = $VarId;            $ArrUpdateData['companyid'] = $this->companyid;            $ArrUpdateData['test_auth_name'] = $VarTestingAuth;            $ArrUpdateData['address'] = $VarAddress;            $ArrUpdateData['gst'] = $VarGst;            $ArrUpdateData['contact_name'] = $VarContactName;            $ArrUpdateData['email'] = $VarEmail;            $ArrUpdateData['phone'] = $VarPhone;            $ArrUpdateData['mobile'] = $VarMobile;            $ArrUpdateData['status'] = $VarStatus;            $ArrUpdateData['updatedby'] = $this->userid;            $ArrUpdateData['dateupdated'] = date('Y-m-d H:i:s');            /*$ArrUpdateData = array('id' => $VarId, 'companyid' => $this->companyid, 'approvalname' => $VarTestingAuth,                'status' => $VarStatus, 'updatedby' => $this->userid, 'dateupdated' => date('Y-m-d H:i:s'));*/            if ($VarId == '' || $VarId == 0) {                $ArrUpdateData['datecreated'] = date('Y-m-d H:i:s');            }            $ArrResult = $this->mauthmodel->saveInfo($ArrUpdateData);        } else {            $ArrResult['errcode'] = -1;            $ArrResult['msg'] = 'Invalid Input';        }        echo json_encode($ArrResult);    }    public function managetauth() {        $VarFrom = xssclean($this->input->post('rfrom'));        $VarTestingauth = xssclean($this->input->post('ta'));        $VarStatus = xssclean($this->input->post('s'));        $clickedColumnId = xssclean($this->input->post('columnId'));        $newsortorder = xssclean($this->input->post('sortorder'));        $ArrDbCols = array('test_auth_name', 'l.status', 'u.contactname', 'l.dateupdated');        if ($VarFrom == 1) {            $VarURLSegment = 4;            $this->load->library('pagination');            $config['base_url'] = base_url() . CNFCOMPANY . 'mauth/managetauth';            $config['total_rows'] = $this->mauthmodel->fnCount($VarTestingauth, $VarStatus);            $config['per_page'] = $this->limit;            $config['uri_segment'] = $VarURLSegment;            $offset = $this->uri->segment($VarURLSegment);            $this->pagination->initialize($config);            $sortby = "dateupdated";            $sortorder = "desc";            if ($clickedColumnId <> '' && $newsortorder <> '') {                if (array_key_exists($clickedColumnId, $ArrDbCols)) {                    $sortby = $ArrDbCols[$clickedColumnId];                }                $sortorder = $newsortorder;            }            $ArrList = $this->mauthmodel->fnList($VarTestingauth, $VarStatus, $this->limit, $offset, $sortby, $sortorder)->result();            $data['pagination'] = $this->pagination->create_linkswithajax('Testingauth');            $i = 0;            $ArrFnlList = array();            $ArrStatus = unserialize(ARRSTATUS);            foreach ($ArrList as $Obj) {                $ArrFnlList[$i]['id'] = $Obj->id;                $ArrFnlList[$i]['i'] = $Obj->test_auth_name;                $ArrFnlList[$i]['ub'] = $Obj->contactname;                $ArrFnlList[$i]['s'] = $ArrStatus[$Obj->status];                $ArrFnlList[$i]['du'] = date('d-m-Y H:i:s', strtotime($Obj->dateupdated));                $i = $i + 1;            }            echo json_encode(array('errcode' => 1, 'cn' => $config['total_rows'], 'ct' => $i, 're' => $ArrFnlList, 'pa' => base64_encode($data['pagination'])));            unset($ArrFnlList);            die;        } else {            $this->load->view(CNFCOMPANY . 'manageauths', array());        }    }    function changeStatus() {        $VarActDeactOption = xssclean($this->input->post('actDeact'));        $VarCid = xssclean($this->input->post('cid'));        if ($VarActDeactOption <> '' && $VarCid <> '') {            $this->mauthmodel->fnChangeStat($VarCid, $VarActDeactOption);        }        echo json_encode(array('errcode' => 1));        die;    }}